class string_buf;

class stringx
{
    char *chars;
    string_buf *my_buf;

public:
    stringx(const char *value, int length = -1);
    stringx(const stringx &other);
    ~stringx();
    stringx &operator=(const stringx &other);
    int length() const;
    char &operator[](int index);
};

struct nglFileBuf
{
    unsigned char *Buf;
    unsigned int Size;
    unsigned int UserData;
};

class TextString
{
protected:
    void *font;
    stringx text;
    float x;
    float y;
    int z;
    int hJustify;
    int vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    bool checkTime;
    float time;
    bool no_color;
    unsigned int color;

    virtual ~TextString();
};

class BoxText : public TextString
{
    int width;
    int height;
    bool reverse;
    int max_box_strings;
    void *box_strings;
    int box_str_count;
    nglFileBuf fileBuf;
    bool non_floating_behavior;
    float remaining_fields[16];

public:
    void ReadFromFile(char *filename, bool remove_endlines);
};

bool mem_malloc_locked();
void mem_lock_malloc(bool locked);
bool KSReadFile(const char *filename, nglFileBuf *file, unsigned int align);
void KSReleaseFile(nglFileBuf *file);
void nglPrintf(const char *format, ...);
void MakeReplacements(stringx &value);

void BoxText::ReadFromFile(char* filename, bool remove_endlines)
{
	bool locked = mem_malloc_locked();
	mem_lock_malloc(false);

	fileBuf.Buf=NULL; fileBuf.Size=0;
	KSReadFile(filename, &fileBuf, 1);
	unsigned char* buffer = (unsigned char*) fileBuf.Buf;
	if(!buffer)
	{
		KSReleaseFile(&fileBuf);
		nglPrintf("File %s is missing\n", filename);
		return;
	}

	buffer[fileBuf.Size] = '\0';	// terminate string, using the extra byte allocated in wds_readfile (dc 05/19/02)
	text = stringx((char*) buffer);
	if(remove_endlines)
	{
		for(int i=0; i<text.length(); i++)
			if(text[i] == '\n') text[i] = ' ';
	}
	KSReleaseFile(&fileBuf);
	mem_lock_malloc(locked);
	MakeReplacements(text);
}
